network_policy_prototype.policy_source:
import path from 'node:path';

const marker = 'SPECWRIGHT_OMP_LOCAL_ONLY';
const tools = new Set(['read', 'grep', 'glob']);
const driveAbsolute = /^[A-Za-z]:[\\/](?![\\/])/;
const scheme = /^[A-Za-z][A-Za-z0-9+.-]*:/;

function localAbsolute(value) {
  if (value.startsWith('\\\\') || value.startsWith('//')) return false;
  return process.platform === 'win32' ? driveAbsolute.test(value) : value.startsWith('/');
}

export default function (api) {
  api.on('tool_call', (event, context) => {
    if (!tools.has(event.toolName)) return;
    try {
      if (!localAbsolute(context.cwd)) throw new Error('working directory must be a local absolute path');
      const input = event.input;
      const raw = input.path;
      if (raw !== undefined && raw !== null && typeof raw !== 'string') throw new Error('target must be a string');
      const target = raw === undefined || raw === null || raw === '' ? context.cwd : raw.trim();
      if (!target || target.includes('\0')) throw new Error('target is empty or contains NUL');
      if (target.startsWith('\\\\') || target.startsWith('//')) throw new Error('network shares are not local targets');
      if (/^www\./i.test(target) || (scheme.test(target) && !driveAbsolute.test(target))) throw new Error('URI targets are forbidden; use ./ for a local filename with a selector');
      if (event.toolName !== 'read' && (target.includes(';') || /^\s*\[/.test(target))) throw new Error('this experimental gate accepts one search root per call');
      const absolute = path.resolve(context.cwd, target);
      if (!localAbsolute(absolute)) throw new Error('target did not resolve to a local absolute path');
      return {input: {...input, path: absolute}};
    } catch (error) {
      return {block: true, reason: marker + ': ' + String(error.message || error)};
    }
  });
}

